package org.thesis.eval;

import com.github.javaparser.ast.*;import com.github.javaparser.ast.body.*;import com.github.javaparser.ast.expr.*;import com.github.javaparser.ast.type.*;import com.github.javaparser.resolution.declarations.*;import com.github.javaparser.resolution.types.*;
import java.nio.file.*;import java.util.*;

final class DependencyExtractor {
 private final SourceIndex idx; private final Config cfg; private final Models.Closure out; private final Set<String> visited=new HashSet<>();
 DependencyExtractor(SourceIndex idx,Config cfg,Models.ManifestRow method){this.idx=idx;this.cfg=cfg;out=new Models.Closure();out.method=method;}
 Models.Closure extract()throws Exception{Models.ManifestRow m=out.method;Path src=idx.repo.resolve(m.sourceFile());if(!Files.exists(src)){out.sourceStatus="SOURCE_FILE_MISSING";out.diagnostics.add("Missing source file: "+m.sourceFile());return out;}CompilationUnit cu=idx.parser.parse(src).getResult().orElse(null);if(cu==null){out.sourceStatus="SOURCE_PARSE_FAILED";return out;}String owner=locateOwner(cu,m);MethodDeclaration target=locateTarget(cu,m);if(target==null){out.sourceStatus="TARGET_NOT_FOUND";return out;}if(owner.isBlank())owner=target.findAncestor(TypeDeclaration.class).map(t->idx.fqnFor((TypeDeclaration<?>)t)).orElse(m.className());out.rootOwner=owner;out.rootSignature=target.getDeclarationAsString(false,false,true);out.sourceStatus="RESOLVED";addHierarchy(owner,target,0,"TARGET",m.methodName());traverseMethod(owner,target,0,"TARGET",m.methodName());return out;}
 private String locateOwner(CompilationUnit cu,Models.ManifestRow m){for(TypeDeclaration<?> t:cu.findAll(TypeDeclaration.class))if(t.getNameAsString().equals(m.className()))return idx.fqnFor(t);for(TypeDeclaration<?> t:cu.getTypes())if(t.getMethodsByName(m.methodName()).size()>0)return idx.fqnFor(t);return "";}
 private MethodDeclaration locateTarget(CompilationUnit cu,Models.ManifestRow m){List<MethodDeclaration> ms=cu.findAll(MethodDeclaration.class).stream().filter(x->x.getNameAsString().equals(m.methodName())).toList();if(ms.size()==1)return ms.get(0);for(MethodDeclaration x:ms){if(x.getRange().isPresent()){int b=x.getRange().get().begin.line,e=x.getRange().get().end.line;if(m.lineStart()>=b&&m.lineStart()<=e)return x;}}return ms.isEmpty()?null:ms.get(0);}
 private void traverseMethod(String owner,MethodDeclaration md,int depth,String parent,String path){if(depth>cfg.integer("groundtruth.max.depth",50))return;String vk="M|"+owner+"|"+md.getNameAsString()+"/"+md.getParameters().size();if(!visited.add(vk))return;scan(owner,md,depth,parent,path);}
 private void traverseCtor(String owner,ConstructorDeclaration cd,int depth,String parent,String path){if(depth>cfg.integer("groundtruth.max.depth",50))return;String vk="C|"+owner+"|"+cd.getParameters().size();if(!visited.add(vk))return;scan(owner,cd,depth,parent,path);}
 private void traverseField(String owner,FieldDeclaration fd,int depth,String parent,String path){for(VariableDeclarator v:fd.getVariables()){String vk="F|"+owner+"|"+v.getNameAsString();if(!visited.add(vk))continue;addTypeNode(v.getType(),depth+1,parent,path+" -> "+v.getNameAsString());v.getInitializer().ifPresent(x->scanNode(owner,x,depth+1,parent,path+" -> "+v.getNameAsString()));}}
 private void scan(String owner,CallableDeclaration<?> cd,int depth,String parent,String path){for(Parameter p:cd.getParameters())addTypeNode(p.getType(),depth,parent,path);if(cd instanceof MethodDeclaration md)addTypeNode(md.getType(),depth,parent,path);for(AnnotationExpr a:cd.getAnnotations())addAnnotation(a,depth,parent,path);scanNode(owner,cd,depth,parent,path);}
 private void scanNode(String currentOwner,Node node,int depth,String parent,String path){
   for(ClassOrInterfaceType t:node.findAll(ClassOrInterfaceType.class))addTypeNode(t,depth+1,parent,path);
   for(MethodCallExpr mc:node.findAll(MethodCallExpr.class)){String child=mc.getNameAsString();try{ResolvedMethodDeclaration r=mc.resolve();String o=r.declaringType().getQualifiedName();String sig=r.getQualifiedSignature();Models.Provenance pv=prov(o);Models.Dep d=new Models.Dep(Models.Kind.METHOD,o,r.getName(),sig,pv,depth+1,parent,path+" -> "+o+"."+r.getName(),idx.sourceOf(o),"RESOLVED");out.add(d);if(idx.isRepository(o))idx.method(o,r.getName(),r.getNumberOfParams()).ifPresent(x->traverseMethod(o,x,depth+1,d.id(),d.path));}catch(Throwable e){String o=inferScope(mc.getScope().orElse(null),currentOwner);Models.Dep d=new Models.Dep(Models.Kind.METHOD,o,child,child+"/"+mc.getArguments().size(),prov(o),depth+1,parent,path+" -> "+(o.isBlank()?"":o+".")+child,idx.sourceOf(o),"SYNTACTIC_FALLBACK");out.add(d);out.diagnostics.add("Unresolved call: "+mc+" :: "+SourceIndex.shortMsg(e));}}
   for(ObjectCreationExpr oc:node.findAll(ObjectCreationExpr.class)){try{ResolvedConstructorDeclaration r=oc.resolve();String o=r.declaringType().getQualifiedName();Models.Dep d=new Models.Dep(Models.Kind.CONSTRUCTOR,o,"<init>",r.getQualifiedSignature(),prov(o),depth+1,parent,path+" -> new "+o,idx.sourceOf(o),"RESOLVED");out.add(d);if(idx.isRepository(o))idx.ctor(o,r.getNumberOfParams()).ifPresent(x->traverseCtor(o,x,depth+1,d.id(),d.path));}catch(Throwable e){String o=oc.getType().getNameWithScope();Models.Dep d=new Models.Dep(Models.Kind.CONSTRUCTOR,o,"<init>","<init>/"+oc.getArguments().size(),prov(o),depth+1,parent,path+" -> new "+o,idx.sourceOf(o),"SYNTACTIC_FALLBACK");out.add(d);}}
   for(FieldAccessExpr fa:node.findAll(FieldAccessExpr.class))addFieldAccess(currentOwner,fa,depth,parent,path);
   for(NameExpr ne:node.findAll(NameExpr.class)){try{ResolvedValueDeclaration v=ne.resolve();if(v.isField()){ResolvedFieldDeclaration f=v.asField();String o=f.declaringType().getQualifiedName();Models.Dep d=new Models.Dep(Models.Kind.FIELD,o,f.getName(),f.getType().describe(),prov(o),depth+1,parent,path+" -> "+o+"."+f.getName(),idx.sourceOf(o),"RESOLVED");out.add(d);if(idx.isRepository(o))idx.field(o,f.getName()).ifPresent(x->traverseField(o,x,depth+1,d.id(),d.path));}}catch(Throwable ignored){}}
   for(AnnotationExpr a:node.findAll(AnnotationExpr.class))addAnnotation(a,depth+1,parent,path);
 }
 private void addFieldAccess(String currentOwner,FieldAccessExpr fa,int depth,String parent,String path){try{ResolvedValueDeclaration v=fa.resolve();if(v.isField()){ResolvedFieldDeclaration f=v.asField();String o=f.declaringType().getQualifiedName();Models.Dep d=new Models.Dep(Models.Kind.FIELD,o,f.getName(),f.getType().describe(),prov(o),depth+1,parent,path+" -> "+o+"."+f.getName(),idx.sourceOf(o),"RESOLVED");out.add(d);if(idx.isRepository(o))idx.field(o,f.getName()).ifPresent(x->traverseField(o,x,depth+1,d.id(),d.path));}}catch(Throwable e){String o=inferScope(fa.getScope(),currentOwner);out.add(new Models.Dep(Models.Kind.FIELD,o,fa.getNameAsString(),"",prov(o),depth+1,parent,path+" -> "+o+"."+fa.getNameAsString(),idx.sourceOf(o),"SYNTACTIC_FALLBACK"));}}
 private void addTypeNode(Type t,int depth,String parent,String path){String q="";try{ResolvedType rt=t.resolve();q=SourceIndex.raw(rt.describe());}catch(Throwable e){q=SourceIndex.raw(t.asString());}if(q.isBlank()||primitive(q))return;Models.Provenance pv=prov(q);out.add(new Models.Dep(Models.Kind.TYPE,q,"",q,pv,depth,parent,path+" -> "+q,idx.sourceOf(q),"TYPE"));if(idx.isRepository(q))addHierarchy(q,null,depth,parent,path);}
 private void addAnnotation(AnnotationExpr a,int depth,String parent,String path){String q=a.getNameAsString();try{q=a.resolve().getQualifiedName();}catch(Throwable ignored){}out.add(new Models.Dep(Models.Kind.ANNOTATION,q,a.getNameAsString(),q,prov(q),depth,parent,path+" -> @"+q,idx.sourceOf(q),"ANNOTATION"));}
 private void addHierarchy(String owner,MethodDeclaration md,int depth,String parent,String path){TypeDeclaration<?> td=idx.types.get(SourceIndex.raw(owner));if(td instanceof ClassOrInterfaceDeclaration c){for(ClassOrInterfaceType e:c.getExtendedTypes()){String q=resolveType(e);out.add(new Models.Dep(Models.Kind.SUPERCLASS,q,"",q,prov(q),depth+1,parent,path+" -> extends "+q,idx.sourceOf(q),"HIERARCHY"));}for(ClassOrInterfaceType e:c.getImplementedTypes()){String q=resolveType(e);out.add(new Models.Dep(Models.Kind.INTERFACE,q,"",q,prov(q),depth+1,parent,path+" -> implements "+q,idx.sourceOf(q),"HIERARCHY"));}}}
 private String resolveType(ClassOrInterfaceType t){try{return SourceIndex.raw(t.resolve().describe());}catch(Throwable e){return t.getNameWithScope();}}
 private Models.Provenance prov(String fqn){String q=SourceIndex.raw(fqn);if(q.isBlank())return Models.Provenance.UNRESOLVED;if(idx.isRepository(q))return Models.Provenance.REPOSITORY;if(q.startsWith("java.")||q.startsWith("javax.")||q.startsWith("jdk."))return Models.Provenance.JDK;if(idx.hasMaven)return Models.Provenance.EXTERNAL_MAVEN;if(idx.hasGradle)return Models.Provenance.EXTERNAL_GRADLE;return Models.Provenance.EXTERNAL_OTHER;}
 private String inferScope(Expression e,String currentOwner){if(e==null)return currentOwner;if(e.isThisExpr())return currentOwner;if(e.isNameExpr()){String n=e.asNameExpr().getNameAsString();for(String f:idx.types.keySet())if(Models.Dep.simple(f).equals(n))return f;}return e.toString();}
 private static boolean primitive(String q){return Set.of("void","boolean","byte","short","int","long","float","double","char","var").contains(q);}
}
